// Registro de usuarios
// ==========================================================

import { generateUserUUID } from "../security/uuid.js";
import { hashPassword } from "../security/hash.js";
import { createUser } from "../database/users.js";

const corsHeaders = {
    "Access-Control-Allow-Origin": "https://ligronair.tv",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};

export async function register(request, env) {

    try {

        const body = await request.json();

        const nombre = body.nombre?.trim();

        const email = body.email?.trim().toLowerCase();

        const password = body.password;

        if (!nombre || !email || !password) {

            return Response.json(
                {
                    success: false,
                    error: "Faltan datos obligatorios."
                },
                {
                    status: 400,
                    headers: corsHeaders
                }
            );

        }

        const uuid = generateUserUUID();

        const passwordHash = await hashPassword(password);

        await createUser(env.DB, {

            uuid,

            nombre,

            email,

            passwordHash

        });

        console.info("LigronLink: cuenta creada.");

        return Response.json(
            {
                success: true,
                uuid,
                message: "Cuenta creada correctamente."
            },
            {
                headers: corsHeaders
            }
        );

    }

    catch (error) {

        console.error("ERROR EN REGISTER");

        console.error(error);

        return Response.json(
            {
                success: false,
                error: error.message
            },
            {
                status: 500,
                headers: corsHeaders
            }
        );

    }

}
