// ==========================================================
// Registrar o actualizar receptores SRT de un equipo.
// ==========================================================

export async function replaceSrtDestinations(db, device, receivers) {

    // ======================================================
    // ### FIX
    // La publicación se trata como una fotografía completa
    // de los receptores del equipo. Los anteriores se ponen
    // OFFLINE antes de actualizar los recibidos.
    // ======================================================

    await db
        .prepare(
            `
            UPDATE srt_destinos
            SET
                -- Una reserva se conserva sólo mientras el Pi que la
                -- solicitó siga presente. Así una reserva legítima soporta
                -- un nuevo snapshot de Native, pero una reserva abandonada
                -- vuelve a quedar disponible al siguiente heartbeat.
                estado = CASE
                    WHEN estado = 'RESERVED'
                     AND ?3 != 'OFFLINE'
                     AND EXISTS (
                        SELECT 1
                        FROM equipos AS pi
                        WHERE pi.uuid = srt_destinos.reservado_por_uuid
                          AND pi.usuario_id = srt_destinos.usuario_id
                          AND UPPER(pi.estado) = 'ONLINE'
                          AND datetime(pi.ultima_conexion) >= datetime('now', '-75 seconds')
                     ) THEN 'RESERVED'
                    ELSE 'OFFLINE'
                END,
                ultima_actualizacion = datetime('now')
            WHERE equipo_uuid = ?1
              AND usuario_id = ?2
            `
        )
        .bind(
            device.uuid,
            device.usuarioId,
            receivers.some((receiver) => receiver.estado !== 'OFFLINE') ? 'FREE' : 'OFFLINE'
        )
        .run();

    const guardados = [];

    for (const receiver of receivers) {

        await db
            .prepare(
                `
                INSERT INTO srt_destinos
                (
                    equipo_uuid,
                    usuario_id,
                    source_id,
                    nombre,
                    host,
                    port,
                    mode,
                    estado,
                    reservado_por_uuid,
                    ultima_actualizacion,
                    fecha_creacion
                )
                VALUES
                (
                    ?1,
                    ?2,
                    ?3,
                    ?4,
                    ?5,
                    ?6,
                    ?7,
                    ?8,
                    NULL,
                    datetime('now'),
                    datetime('now')
                )
                ON CONFLICT(equipo_uuid, source_id)
                DO UPDATE SET
                    usuario_id = excluded.usuario_id,
                    nombre = excluded.nombre,
                    host = excluded.host,
                    port = excluded.port,
                    mode = excluded.mode,
                    -- La reserva pertenece a Link, no al proceso FFmpeg.
                    -- Sobrevive al cambio listener/caller y a sus reintentos
                    -- mientras la Pi continúe con presencia reciente.
                    estado = CASE
                        WHEN srt_destinos.estado = 'RESERVED'
                         AND excluded.estado != 'OFFLINE'
                         AND EXISTS (
                            SELECT 1
                            FROM equipos AS pi
                            WHERE pi.uuid = srt_destinos.reservado_por_uuid
                              AND pi.usuario_id = srt_destinos.usuario_id
                              AND UPPER(pi.estado) = 'ONLINE'
                              AND datetime(pi.ultima_conexion) >= datetime('now', '-75 seconds')
                         )
                            THEN 'RESERVED'
                        ELSE excluded.estado
                    END,
                    reservado_por_uuid = CASE
                        WHEN srt_destinos.estado = 'RESERVED'
                         AND excluded.estado != 'OFFLINE'
                         AND EXISTS (
                            SELECT 1
                            FROM equipos AS pi
                            WHERE pi.uuid = srt_destinos.reservado_por_uuid
                              AND pi.usuario_id = srt_destinos.usuario_id
                              AND UPPER(pi.estado) = 'ONLINE'
                              AND datetime(pi.ultima_conexion) >= datetime('now', '-75 seconds')
                         )
                            THEN srt_destinos.reservado_por_uuid
                        ELSE NULL
                    END,
                    ultima_actualizacion = datetime('now')
                `
            )
            .bind(
                device.uuid,
                device.usuarioId,
                receiver.sourceId,
                receiver.nombre,
                receiver.host,
                receiver.port,
                receiver.mode,
                receiver.estado
            )
            .run();

        guardados.push({
            source_id: receiver.sourceId,
            name: receiver.nombre,
            host: receiver.host,
            port: receiver.port,
            mode: receiver.mode,
            state: receiver.estado
        });

    }

    return guardados;

}

// ==========================================================
// Comparar la fotografía que Native quiere publicar con la ya
// almacenada. Un heartbeat no debe reescribir cincuenta filas
// si los listeners siguen exactamente igual.
// ==========================================================

export async function hasSameSrtReceiverSnapshot(db, device, receivers) {

    const current = await db.prepare(`
        SELECT source_id, nombre, host, port, mode, estado
        FROM srt_destinos
        WHERE equipo_uuid = ?1 AND usuario_id = ?2
        ORDER BY source_id
    `).bind(device.uuid, device.usuarioId).all();

    const rows = current.results || [];
    if (rows.length !== receivers.length) return false;

    const bySourceId = new Map(rows.map((row) => [Number(row.source_id), row]));
    return receivers.every((receiver) => {
        const row = bySourceId.get(Number(receiver.sourceId));
        if (!row) return false;
        const persistedState = String(row.estado || "").toUpperCase();
        const requestedState = String(receiver.estado || "").toUpperCase();
        // RESERVED es una decisión de Link. Native sigue publicando FREE
        // mientras su listener está preparado y no debe borrar la reserva.
        const compatibleState = persistedState === requestedState
            || (persistedState === "RESERVED" && requestedState === "FREE");
        return String(row.nombre) === String(receiver.nombre)
            && String(row.host) === String(receiver.host)
            && Number(row.port) === Number(receiver.port)
            && String(row.mode) === String(receiver.mode)
            && compatibleState;
    });

}

// ==========================================================
// ### FIX
// Resumen de receptores SRT por equipo para el dashboard web.
// ==========================================================

export async function findSrtReceiverSummaryByUser(db, usuarioId) {

    const resultado = await db
        .prepare(
            `
            SELECT
                equipo_uuid,
                COUNT(*) AS total,
                SUM(CASE WHEN estado = 'FREE' THEN 1 ELSE 0 END) AS free,
                SUM(CASE WHEN estado = 'BUSY' THEN 1 ELSE 0 END) AS busy,
                SUM(CASE WHEN estado = 'RESERVED' THEN 1 ELSE 0 END) AS reserved,
                SUM(CASE WHEN estado = 'OFFLINE' THEN 1 ELSE 0 END) AS offline,
                MAX(ultima_actualizacion) AS last_update
            FROM srt_destinos
            WHERE usuario_id = ?1
            GROUP BY equipo_uuid
            `
        )
        .bind(usuarioId)
        .all();

    return resultado.results;

}

// ==========================================================
// ### FIX
// Lista completa de receptores SRT por usuario para desplegable web.
// ==========================================================

export async function findSrtReceiversByUser(db, usuarioId) {

    const resultado = await db
        .prepare(
            `
            SELECT
                s.id,
                s.equipo_uuid,
                s.source_id,
                s.nombre,
                s.host,
                s.port,
                s.mode,
                s.estado,
                s.reservado_por_uuid,
                pi.alias AS reserved_by_alias,
                s.ultima_actualizacion
            FROM srt_destinos AS s
            LEFT JOIN equipos AS pi
                ON pi.uuid = s.reservado_por_uuid
               AND pi.usuario_id = s.usuario_id
            WHERE s.usuario_id = ?1
            ORDER BY
                s.equipo_uuid ASC,
                s.source_id ASC
            `
        )
        .bind(usuarioId)
        .all();

    return resultado.results;

}

// ==========================================================
// ### FIX
// Obtener equipos LigronAir con receptores libres agrupados.
// ==========================================================

export async function findAvailableSrtDevices(db, usuarioId) {

    const resultado = await db
        .prepare(
            `
            SELECT
                s.equipo_uuid,
                e.alias AS device_alias,
                COUNT(*) AS available_receivers
            FROM srt_destinos AS s
            INNER JOIN equipos AS e
                ON e.uuid = s.equipo_uuid
            WHERE s.usuario_id = ?1
              AND s.estado = 'FREE'
              AND e.usuario_id = ?1
              AND UPPER(e.estado) = 'ONLINE'
              AND datetime(e.ultima_conexion) >= datetime('now', '-75 seconds')
              AND LOWER(TRIM(e.tipo)) IN (
                  'ligronair',
                  'ligronair native',
                  'ligronair_native'
              )
              AND s.port BETWEEN 1 AND 65535
            GROUP BY
                s.equipo_uuid,
                e.alias
            HAVING COUNT(*) > 0
            ORDER BY
                e.alias ASC
            `
        )
        .bind(usuarioId)
        .all();

    return resultado.results;

}

// ==========================================================
// Obtener destinos SRT utilizables por un usuario.
// ==========================================================

export async function findAvailableSrtDestinations(db, usuarioId) {

    const resultado = await db
        .prepare(
            `
            SELECT
                s.id,
                s.equipo_uuid,
                e.alias AS device_alias,
                s.source_id,
                s.nombre,
                s.host,
                s.port,
                s.mode,
                s.estado,
                s.reservado_por_uuid,
                s.ultima_actualizacion
            FROM srt_destinos AS s
            INNER JOIN equipos AS e
                ON e.uuid = s.equipo_uuid
            WHERE s.usuario_id = ?1
              AND s.estado = 'FREE'
              AND e.usuario_id = ?1
              AND UPPER(e.estado) = 'ONLINE'
              AND datetime(e.ultima_conexion) >= datetime('now', '-75 seconds')
              AND LOWER(TRIM(e.tipo)) IN (
                  'ligronair',
                  'ligronair native',
                  'ligronair_native'
              )
              AND s.port BETWEEN 1 AND 65535
            ORDER BY
                e.alias ASC,
                s.source_id ASC
            `
        )
        .bind(usuarioId)
        .all();

    return resultado.results;

}

// ==========================================================
// ### FIX
// Reservar atómicamente un receptor FREE de un LigronAir.
// ==========================================================

export async function allocateSrtDestination(db, usuarioId, piUuid, deviceUuid, sourceId = null) {

    // Pool reserva primero la vía y después ordena a la Pi que la prepare.
    // Cuando la Pi recibe la orden, su llamada normal a /srt/allocate debe
    // recuperar *esa misma* reserva, no buscar una caja libre distinta ni
    // tratar la operación como un fallo. Esta comprobación es idempotente y
    // no concede acceso a reservas de otra Pi.
    if (sourceId !== null) {
        const existing = await db.prepare(`
            SELECT
                s.id, s.equipo_uuid, s.source_id, s.nombre, s.host, s.port,
                s.mode, s.estado, s.reservado_por_uuid
            FROM srt_destinos AS s
            INNER JOIN equipos AS e ON e.uuid = s.equipo_uuid
            WHERE s.usuario_id = ?1
              AND s.equipo_uuid = ?3
              AND s.source_id = ?4
              AND s.estado = 'RESERVED'
              AND s.reservado_por_uuid = ?2
              AND e.usuario_id = ?1
              AND UPPER(e.estado) = 'ONLINE'
              AND datetime(e.ultima_conexion) >= datetime('now', '-75 seconds')
              AND s.port BETWEEN 1 AND 65535
            LIMIT 1
        `).bind(usuarioId, piUuid, deviceUuid, sourceId).first();
        if (existing) return existing;
    }

    const resultado = await db
        .prepare(
            `
            UPDATE srt_destinos
            SET
                estado = 'RESERVED',
                reservado_por_uuid = ?2,
                ultima_actualizacion = datetime('now')
            WHERE id = (
                SELECT
                    s.id
                FROM srt_destinos AS s
                INNER JOIN equipos AS e
                    ON e.uuid = s.equipo_uuid
                WHERE s.usuario_id = ?1
                  AND s.equipo_uuid = ?3
                  AND (?4 IS NULL OR s.source_id = ?4)
                  AND s.estado = 'FREE'
                  AND e.usuario_id = ?1
                  AND UPPER(e.estado) = 'ONLINE'
                  AND datetime(e.ultima_conexion) >= datetime('now', '-75 seconds')
                  AND LOWER(TRIM(e.tipo)) IN (
                      'ligronair',
                      'ligronair native',
                      'ligronair_native'
                  )
                  AND s.port BETWEEN 1 AND 65535
                ORDER BY
                    s.source_id ASC
                LIMIT 1
            )
            AND estado = 'FREE'
            RETURNING
                id,
                equipo_uuid,
                source_id,
                nombre,
                host,
                port,
                mode,
                estado,
                reservado_por_uuid
            `
        )
        .bind(
            usuarioId,
            piUuid,
            deviceUuid,
            sourceId
        )
        .first();

    return resultado;

}

// ==========================================================
// ### FIX
// Liberar de forma idempotente las reservas de una Pi.
// ==========================================================

export async function releaseSrtDestination(db, usuarioId, piUuid, deviceUuid) {

    const resultado = await db
        .prepare(
            `
            UPDATE srt_destinos
            SET
                estado = 'FREE',
                reservado_por_uuid = NULL,
                ultima_actualizacion = datetime('now')
            WHERE usuario_id = ?1
              AND reservado_por_uuid = ?2
              AND equipo_uuid = ?3
              AND estado = 'RESERVED'
            `
        )
        .bind(
            usuarioId,
            piUuid,
            deviceUuid
        )
        .run();

    return resultado.meta?.changes || 0;

}
